class Solution {
  public int minArrivalsToDiscard(int[] arrivals, int w, int m) {
    int n = arrivals.length, discarded = 0;
    int[] count = new int[100_001];
    boolean[] kept = new boolean[n];
    for (int i = 0; i < n; i++) {
      if (i >= w && kept[i - w]) count[arrivals[i - w]]--;
      if (count[arrivals[i]] >= m) {
        discarded++;
      } else {
        kept[i] = true;
        count[arrivals[i]]++;
      }
    }
    return discarded;
  }
}
